import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class Main {
    static void placeOrder(Connection connection, long productId, int quantity) throws SQLException {
        if (quantity <= 0) throw new IllegalArgumentException("Quantity must be positive");
        boolean previousAutoCommit = connection.getAutoCommit();
        connection.setAutoCommit(false);
        try {
            try (PreparedStatement stock = connection.prepareStatement(
                    "UPDATE product SET stock = stock - ? WHERE id = ? AND stock >= ?")) {
                stock.setInt(1, quantity); stock.setLong(2, productId); stock.setInt(3, quantity);
                if (stock.executeUpdate() != 1) throw new SQLException("Product missing or insufficient stock");
            }
            try (PreparedStatement order = connection.prepareStatement(
                    "INSERT INTO customer_order(product_id, quantity) VALUES (?, ?)")) {
                order.setLong(1, productId); order.setInt(2, quantity); order.executeUpdate();
            }
            connection.commit();
        } catch (SQLException | RuntimeException failure) {
            connection.rollback();
            throw failure;
        } finally {
            connection.setAutoCommit(previousAutoCommit);
        }
    }
    public static void main(String[] args) throws Exception {
        String url = System.getenv("JDBC_URL");
        if (url == null || url.isBlank()) throw new IllegalStateException("Set JDBC_URL");
        try (Connection connection = DriverManager.getConnection(url, System.getenv("JDBC_USER"), System.getenv("JDBC_PASSWORD"))) {
            placeOrder(connection, 1L, 2);
            System.out.println("Order committed");
        }
    }
}
